//! Actual persisted-window popularity and shared public/native view transaction.
//! All accounts, events and visitor hashes belong only to the disposable fixture.
use serde_json::{Value,json};
use std::{collections::BTreeMap,time::Duration};
use weebdex_platform::{AppState,Config,domains,public_api::{PostgresPublicIdResolver,PublicIdResolver,PublicUuid,ResourceKind}};
struct Server(tokio::task::JoinHandle<()>);impl Drop for Server{fn drop(&mut self){self.0.abort();}}
async fn get(c:&reqwest::Client,origin:&str,path:&str,status:u16)->Value{
 let r=c.get(format!("{origin}/api/v1{path}")).send().await.unwrap();assert_eq!(r.status().as_u16(),status,"{path}");assert!(r.headers()["cache-control"].to_str().unwrap().contains("no-store"));let v:Value=r.json().await.unwrap();if status!=200{assert_eq!(v["result"],"error");}v
}
fn observed(v:&Value,time:&str,seconds:i64){let n=&v["nostr"];assert_eq!(n["scope"],"instance-catalogue");assert_eq!(n["source"],"persisted-native-view-events");assert_eq!(n["metric"],"deduplicated-views");assert_eq!(n["rank"],"read");assert_eq!(n["time"],time);assert_eq!(n["windowSeconds"],seconds);assert_eq!(n["order"],"window-views-desc-native-id-asc");let clock=n["observedAt"].as_str().unwrap();assert_eq!(clock.len(),27);assert!(clock.ends_with('Z'));assert_eq!(&clock[19..20],".");assert!(clock[20..26].bytes().all(|b|b.is_ascii_digit()));}
fn rows(v:&Value)->Vec<(String,String)>{v["data"].as_array().unwrap().iter().map(|x|(x["id"].as_str().unwrap().to_owned(),x["attributes"]["nostr"]["popularity"]["views"].as_str().unwrap().to_owned())).collect()}
async fn actual_client_probe(origin:&str,manga:&PublicUuid,chapter:&PublicUuid,runtime:&std::path::Path){
 use sha2::{Digest,Sha256};
 let hash=|bytes:&[u8]|hex::encode(Sha256::digest(bytes));
 let checkout=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().canonicalize().unwrap();
 let script=checkout.join("tests/ci/probe_public_popularity.mjs").canonicalize().expect("compose the mandatory current-checkout popularity probe before qualification");
 assert!(script.starts_with(&checkout));
 let script_hash=hash(include_bytes!("../../tests/ci/probe_public_popularity.mjs"));
 assert_eq!(hash(&std::fs::read(&script).unwrap()),script_hash,"runtime script must match the compiled probe bytes");
 let expected=BTreeMap::from([
  ("client.ts",hash(include_bytes!("../../platform-integrations/public-api/client.ts"))),
  ("popularity.ts",hash(include_bytes!("../../platform-integrations/public-api/popularity.ts"))),
  ("query.ts",hash(include_bytes!("../../platform-integrations/public-api/query.ts"))),
  ("validation.ts",hash(include_bytes!("../../platform-integrations/public-api/validation.ts"))),
 ]);
 let receipt=runtime.join("actual-public-popularity-client.json");
 let output=tokio::time::timeout(Duration::from_secs(45),tokio::process::Command::new("node")
  .arg("--experimental-vm-modules").arg(&script).current_dir(&checkout)
  .env("PUBLIC_API_ORIGIN",origin).env("PUBLIC_CLIENT_ORIGIN",origin)
  .env("MANGA_ID",manga.as_str()).env("CHAPTER_ID",chapter.as_str())
  .env("POPULARITY_PROBE_RECEIPT",&receipt).env_remove("EXPECT_INITIAL_EMPTY")
  .kill_on_drop(true).output()).await.expect("actual popularity client exceeded its owned deadline").unwrap();
 assert!(output.status.success(),"current production client probe failed: {}\n{}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));
 let value:Value=serde_json::from_slice(&std::fs::read(&receipt).unwrap()).unwrap();
 assert_eq!(value["status"],"passed");assert_eq!(value["kind"],"actual-public-popularity-client-loopback-probe");
 assert_eq!(value["origin"],origin);assert_eq!(value["targets"],json!({"manga":manga,"chapter":chapter}));
 assert_eq!(value["scriptSha256"],script_hash);assert_eq!(value["sources"],json!(expected),"every executed production module must match its compiled source pin");
 assert_eq!(value["observations"].as_array().unwrap().len(),18);assert_eq!(value["requests"].as_array().unwrap().len(),22);
 assert!(value["rawResponseBytes"].as_u64().unwrap()<=8*1024*1024);assert!(value["elapsedMs"].as_f64().unwrap()<=30000.0);
 assert_eq!(value["cookiePolicy"]["nodeInMemoryJar"],true);assert_eq!(value["cookiePolicy"]["productionSameOriginCredentials"],true);
 assert_eq!(value["cookiePolicy"]["visitorCookieObserved"],true);assert_eq!(value["cookiePolicy"]["valuesRetained"],false);
 assert_eq!(value["cookiePolicy"]["path"],"/api/v1/analytics");assert_eq!(value["cookiePolicy"]["httpOnly"],true);assert_eq!(value["cookiePolicy"]["sameSite"],"Lax");
 eprintln!("Actual current-checkout popularity client: {} observations, {} requests, {} bytes, {}ms; explicit Node cookie jar, no browser claim",value["observations"].as_array().unwrap().len(),value["requests"].as_array().unwrap().len(),value["rawResponseBytes"],value["elapsedMs"]);
}
#[tokio::test(flavor="multi_thread",worker_threads=4)]
#[ignore="Requires isolated scripts/run-auth-tests.sh PostgreSQL"]
async fn genuine_windows_uuid_views_dedup_visibility_rate_and_rollback(){
 let dsn=std::env::var("PLATFORM_AUTH_TEST_DATABASE_URL").expect("isolated runner required");let pg:tokio_postgres::Config=dsn.parse().unwrap();assert_eq!(pg.get_dbname(),Some("weebdex_platform_test"));assert!(pg.get_hosts().iter().all(|h|matches!(h,tokio_postgres::config::Host::Tcp(h) if h=="127.0.0.1")));let runtime=std::path::PathBuf::from(std::env::var("PLATFORM_TEST_RUNTIME_DIR").unwrap());assert!(runtime.join("fixture.json").is_file());
 let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let origin=format!("http://{}",listener.local_addr().unwrap());let state=AppState::connect(Config{public_origin:origin.clone(),database_plaintext_local:true,database_connections:4,uploads_dir:runtime.join("media"),ui_dir:runtime.join("no-ui"),..Config::default()},dsn).await.unwrap();state.db.migrate(domains::MIGRATIONS).await.unwrap();let db=state.db.client().await.unwrap();
 db.batch_execute("INSERT INTO platform.users(id,username,email,password_hash) VALUES('PopulUser1','Popularity fixture','popularity@fixture.invalid','synthetic'); INSERT INTO platform.catalog_manga(id,owner_id,owner_name,title,language,publication_status,content_rating,state) SELECT id,'PopulUser1','Fixture',id,'en','ongoing','safe','published' FROM unnest(ARRAY['PopManga01','PopManga02','PopManga03','PopManga04','PopHidden1','PopAdult01','PopEmpty01'])id; UPDATE platform.catalog_manga SET protocol_source_visible=FALSE WHERE id='PopHidden1';UPDATE platform.catalog_manga SET content_rating='pornographic' WHERE id='PopAdult01'; INSERT INTO platform.catalog_chapters(id,manga_id,uploader_id,uploader_name,language,metadata,published_at) VALUES('PopChap001','PopManga01','PopulUser1','Fixture','en','{\"data\":[{\"file\":\"fixture.webp\",\"dimensions\":[10,10]}]}',clock_timestamp()-interval '1day'),('PopChap002','PopManga02','PopulUser1','Fixture','en','{\"data\":[{\"file\":\"fixture.webp\",\"dimensions\":[10,10]}]}',clock_timestamp()-interval '1day'),('PopChapHid','PopHidden1','PopulUser1','Fixture','en','{\"data\":[{\"file\":\"fixture.webp\",\"dimensions\":[10,10]}]}',clock_timestamp()-interval '1day');INSERT INTO platform.catalog_manga_counters(manga_id,views,follows,rating) VALUES('PopManga04',999999,888888,9.9);").await.unwrap();
 let resolver=PostgresPublicIdResolver::new(state.db.clone());let mut ids=BTreeMap::new();for native in ["PopManga01","PopManga02","PopManga03","PopManga04","PopHidden1","PopAdult01","PopEmpty01"]{ids.insert(native,resolver.preferred(ResourceKind::Manga,native).await.unwrap().unwrap());}for native in ["PopChap001","PopChap002","PopChapHid"]{ids.insert(native,resolver.preferred(ResourceKind::Chapter,native).await.unwrap().unwrap());}
 let alias=PublicUuid::parse("aaaaaaaa-aaaa-8aaa-8aaa-aaaaaaaaaaaa").unwrap();resolver.register_alias(ResourceKind::Manga,"PopManga01",&alias).await.unwrap();let aliases:i64=db.query_one("SELECT count(*) FROM platform.public_resource_ids",&[]).await.unwrap().get(0);
 let app=weebdex_platform::router::router(state.clone());let _server=Server(tokio::spawn(async move{axum::serve(listener,app.into_make_service_with_connect_info::<std::net::SocketAddr>()).await.unwrap();}));let c=reqwest::Client::builder().no_proxy().timeout(Duration::from_secs(15)).build().unwrap();
 for family in ["manga","chapter"]{let v=get(&c,&origin,&format!("/{family}/top?rank=read&time=30d"),200).await;assert_eq!(v["total"],0);assert!(rows(&v).is_empty());observed(&v,"30d",2592000);}
 // Native cumulative counters do not fabricate observed-window rankings.
 for (kind,id,age,count) in [("manga","PopManga01","1hour",2),("manga","PopManga01","8days",8),("manga","PopManga02","1hour",3),("manga","PopManga03","2days",4),("manga","PopHidden1","1hour",20),("manga","PopAdult01","1hour",20),("manga","PopEmpty01","40days",30),("chapter","PopChap001","1hour",2),("chapter","PopChap002","2days",4),("chapter","PopChapHid","1hour",20)]{
  db.execute("INSERT INTO platform.catalog_view_events(entity_type,entity_id,visitor_hash,viewed_at,bucket) SELECT $1,$2,decode(md5($2||$3||i::text),'hex'),clock_timestamp()-$3::text::interval,floor(extract(epoch FROM clock_timestamp()-$3::text::interval)/3600)::bigint FROM generate_series(1,$4::int)i",&[&kind,&id,&age,&count]).await.unwrap();
 }
 for (time,seconds,expected) in [("24h",86400,vec![("PopManga02","3"),("PopManga01","2")]),("7d",604800,vec![("PopManga03","4"),("PopManga02","3"),("PopManga01","2")]),("30d",2592000,vec![("PopManga01","10"),("PopManga03","4"),("PopManga02","3")])]{let v=get(&c,&origin,&format!("/manga/top?rank=read&time={time}&contentRating[]=safe&includes[]=author&includes[]=artist&includes[]=cover_art&includes[]=tag"),200).await;observed(&v,time,seconds);assert_eq!(rows(&v),expected.into_iter().map(|(n,v)|(ids[n].to_string(),v.to_owned())).collect::<Vec<_>>());assert_eq!(v["total"],v["data"].as_array().unwrap().len());for row in v["data"].as_array().unwrap(){assert_eq!(row["attributes"]["nostr"]["popularity"]["time"],time);assert!(row["attributes"]["nostr"]["sortKeys"].is_object());}}
 let adult=get(&c,&origin,"/manga/top?time=24h&contentRating[]=pornographic",200).await;assert_eq!(rows(&adult),vec![(ids["PopAdult01"].to_string(),"20".to_owned())]);
 let limited=get(&c,&origin,"/manga/top?time=30d&limit=1",200).await;assert_eq!(limited["total"],3);assert_eq!(rows(&limited).len(),1);let zero=get(&c,&origin,"/manga/top?limit=0",200).await;assert_eq!(zero["total"],3);assert!(rows(&zero).is_empty());
 let chapters=get(&c,&origin,"/chapter/top?time=7d&includes[]=manga&includes[]=user",200).await;assert_eq!(rows(&chapters),vec![(ids["PopChap002"].to_string(),"4".into()),(ids["PopChap001"].to_string(),"2".into())]);
 // A finite observation window includes no future-dated rows; equal observed
 // scores retain the existing native ID tie order, not a fabricated UUID sort.
 db.batch_execute("INSERT INTO platform.catalog_view_events(entity_type,entity_id,visitor_hash,viewed_at,bucket) SELECT 'manga','PopManga04',decode(md5('tie'||i::text),'hex'),clock_timestamp()-interval '1hour',0 FROM generate_series(1,3)i;INSERT INTO platform.catalog_view_events(entity_type,entity_id,visitor_hash,viewed_at,bucket) VALUES('manga','PopEmpty01',decode(md5('future'),'hex'),clock_timestamp()+interval '1day',0);").await.unwrap();
 let tie=get(&c,&origin,&format!("/manga/top?time=24h&ids[]={}&ids[]={}",ids["PopManga02"],ids["PopManga04"]),200).await;assert_eq!(rows(&tie),vec![(ids["PopManga02"].to_string(),"3".into()),(ids["PopManga04"].to_string(),"3".into())]);let no_future=get(&c,&origin,&format!("/manga/top?ids[]={}",ids["PopEmpty01"]),200).await;assert!(rows(&no_future).is_empty());
 let native_top=c.get(format!("{origin}/api/manga/top?rank=read&time=30d&limit=10")).send().await.unwrap();assert_eq!(native_top.status(),200);let native_top:Value=native_top.json().await.unwrap();assert_eq!(native_top["data"][0]["id"],"PopManga01");assert_eq!(native_top["data"][0]["_sort_value"],10,"the shared native finite-window core also excludes future events and ignores cached counts");
 db.batch_execute("DELETE FROM platform.catalog_view_events WHERE entity_id='PopManga04'").await.unwrap();
 for query in ["time=all","rank=follows","time=24h&time=7d","offset=1","limit=11","order[title]=asc","surprise=1"]{get(&c,&origin,&format!("/manga/top?{query}"),400).await;}
 let view=format!("{origin}/api/v1/analytics/manga/{}/views",ids["PopManga01"]);let first=c.post(&view).send().await.unwrap();assert_eq!(first.status(),204);assert!(first.headers()["cache-control"].to_str().unwrap().contains("no-store"));let set=first.headers()["set-cookie"].to_str().unwrap();assert!(set.contains("Path=/api/v1/analytics")&&set.contains("HttpOnly")&&set.contains("SameSite=Lax"));let cookie=set.split(';').next().unwrap().to_owned();
 let count=||async{db.query_one("SELECT count(*) FROM platform.catalog_view_events WHERE entity_type='manga' AND entity_id='PopManga01'",&[]).await.unwrap().get::<_,i64>(0)};assert_eq!(count().await,11);
 for target in [ids["PopManga01"].to_string(),alias.to_string()]{assert_eq!(c.post(format!("{origin}/api/v1/analytics/manga/{target}/views")).header("cookie",&cookie).send().await.unwrap().status(),204);}assert_eq!(count().await,11,"alias and repeated visitor retain native dedup identity");
 assert_eq!(c.post(format!("{origin}/api/analytics/manga/PopManga01/views")).header("cookie",&cookie).send().await.unwrap().status(),204);assert_eq!(count().await,11,"native and UUID routes share genuine visitor dedup storage");
 assert_eq!(c.post(&view).header("cookie",format!("weebdex_visitor={}","1".repeat(64))).send().await.unwrap().status(),204);assert_eq!(count().await,12);
 let chapter_view=format!("{origin}/api/v1/analytics/chapter/{}/views",ids["PopChap001"]);assert_eq!(c.post(&chapter_view).header("cookie",&cookie).send().await.unwrap().status(),204);assert_eq!(c.post(&chapter_view).header("cookie",&cookie).send().await.unwrap().status(),204);
 let concurrent_url=format!("{origin}/api/v1/analytics/manga/{}/views",ids["PopManga04"]);let concurrent_cookie=format!("weebdex_visitor={}","4".repeat(64));let(a,b)=tokio::join!(c.post(&concurrent_url).header("cookie",&concurrent_cookie).send(),c.post(&concurrent_url).header("cookie",&concurrent_cookie).send());assert_eq!((a.unwrap().status().as_u16(),b.unwrap().status().as_u16()),(204,204));let concurrent=db.query_one("SELECT (SELECT count(*) FROM platform.catalog_view_events WHERE entity_id='PopManga04'),views FROM platform.catalog_manga_counters WHERE manga_id='PopManga04'",&[]).await.unwrap();assert_eq!(concurrent.get::<_,i64>(0),1);assert_eq!(concurrent.get::<_,i64>(1),1000000);
 for (url,code) in [(format!("{origin}/api/v1/analytics/manga/{}/views",ids["PopHidden1"]),404),(format!("{origin}/api/v1/analytics/chapter/{}/views",ids["PopChapHid"]),404),(format!("{origin}/api/v1/analytics/manga/{}/views",ids["PopChap001"]),404),(format!("{view}?extra=1"),400)]{assert_eq!(c.post(url).send().await.unwrap().status().as_u16(),code);}
 assert_eq!(c.post(&view).body("x").send().await.unwrap().status(),400);assert_eq!(c.post(&view).header("origin","https://foreign.invalid").send().await.unwrap().status(),403);assert_eq!(c.post(&view).header("sec-fetch-site","cross-site").send().await.unwrap().status(),403);assert_eq!(count().await,12);
 // Rate identity uses actual loopback transport, not arbitrary XFF or a cookie.
 let rate:i32=db.query_one("SELECT max(count) FROM platform.analytics_rate_limits",&[]).await.unwrap().get(0);assert!(rate>0);db.batch_execute("INSERT INTO platform.analytics_rate_limits(peer_hash,bucket,count) SELECT peer_hash,floor(extract(epoch FROM clock_timestamp())/60)::bigint+i,120 FROM (SELECT DISTINCT peer_hash FROM platform.analytics_rate_limits)peers CROSS JOIN generate_series(0,1)i ON CONFLICT(peer_hash,bucket)DO UPDATE SET count=120").await.unwrap();let limited=c.post(&view).header("cookie",format!("weebdex_visitor={}","2".repeat(64))).header("x-forwarded-for","198.51.100.12").send().await.unwrap();assert_eq!(limited.status(),429);assert_eq!(limited.headers()["retry-after"],"1");assert_eq!(count().await,12);db.batch_execute("DELETE FROM platform.analytics_rate_limits").await.unwrap();
 // A failed actual counter write rolls back event insertion and the rate row.
 db.batch_execute("CREATE FUNCTION platform.pop_fixture_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic view rollback'; END $$;CREATE TRIGGER pop_fixture_fail BEFORE INSERT OR UPDATE ON platform.catalog_manga_counters FOR EACH ROW EXECUTE FUNCTION platform.pop_fixture_fail();").await.unwrap();assert_eq!(c.post(&view).header("cookie",format!("weebdex_visitor={}","3".repeat(64))).send().await.unwrap().status(),503);assert_eq!(count().await,12);assert_eq!(db.query_one("SELECT count(*) FROM platform.analytics_rate_limits",&[]).await.unwrap().get::<_,i64>(0),0);db.batch_execute("DROP TRIGGER pop_fixture_fail ON platform.catalog_manga_counters;DROP FUNCTION platform.pop_fixture_fail()").await.unwrap();
 assert_eq!(db.query_one("SELECT count(*) FROM platform.public_resource_ids",&[]).await.unwrap().get::<_,i64>(0),aliases,"read/views create no aliases");
 actual_client_probe(&origin,&ids["PopEmpty01"],&ids["PopChap001"],&runtime).await;
}
